def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts: dict[str, list] = {}  # name -> [balance, frozen]
    undo_stack: list[tuple] = []
    rejected: list[int] = []

    def valid_amount(s: str) -> bool:
        return len(s) > 0 and all('0' <= c <= '9' for c in s)

    for i, op in enumerate(ops):
        tokens = op.split(' ')
        verb = tokens[0]

        if verb == 'open':
            if len(tokens) != 3 or not valid_amount(tokens[2]):
                rejected.append(i)
                continue
            name = tokens[1]
            if name in accounts:
                rejected.append(i)
                continue
            accounts[name] = [int(tokens[2]), False]
            undo_stack.append(('del', name))

        elif verb == 'deposit':
            if len(tokens) != 3 or not valid_amount(tokens[2]):
                rejected.append(i)
                continue
            name, amt = tokens[1], int(tokens[2])
            if amt <= 0 or name not in accounts:
                rejected.append(i)
                continue
            accounts[name][0] += amt
            undo_stack.append(('sub', name, amt))

        elif verb == 'withdraw':
            if len(tokens) != 3 or not valid_amount(tokens[2]):
                rejected.append(i)
                continue
            name, amt = tokens[1], int(tokens[2])
            if amt <= 0 or name not in accounts:
                rejected.append(i)
                continue
            acc = accounts[name]
            if acc[1] or acc[0] < amt:
                rejected.append(i)
                continue
            acc[0] -= amt
            undo_stack.append(('add', name, amt))

        elif verb == 'transfer':
            if len(tokens) != 4 or not valid_amount(tokens[3]):
                rejected.append(i)
                continue
            a, b, amt = tokens[1], tokens[2], int(tokens[3])
            if amt <= 0 or a == b or a not in accounts or b not in accounts:
                rejected.append(i)
                continue
            acc_a = accounts[a]
            if acc_a[1] or acc_a[0] < amt:
                rejected.append(i)
                continue
            acc_a[0] -= amt
            accounts[b][0] += amt
            undo_stack.append(('xfer', a, b, amt))

        elif verb == 'freeze':
            if len(tokens) != 2:
                rejected.append(i)
                continue
            name = tokens[1]
            if name not in accounts or accounts[name][1]:
                rejected.append(i)
                continue
            accounts[name][1] = True
            undo_stack.append(('frozen', name, False))

        elif verb == 'unfreeze':
            if len(tokens) != 2:
                rejected.append(i)
                continue
            name = tokens[1]
            if name not in accounts or not accounts[name][1]:
                rejected.append(i)
                continue
            accounts[name][1] = False
            undo_stack.append(('frozen', name, True))

        elif verb == 'undo':
            if len(tokens) != 1 or not undo_stack:
                rejected.append(i)
                continue
            action = undo_stack.pop()
            kind = action[0]
            if kind == 'del':
                del accounts[action[1]]
            elif kind == 'sub':
                accounts[action[1]][0] -= action[2]
            elif kind == 'add':
                accounts[action[1]][0] += action[2]
            elif kind == 'xfer':
                accounts[action[2]][0] -= action[3]
                accounts[action[1]][0] += action[3]
            elif kind == 'frozen':
                accounts[action[1]][1] = action[2]

        else:
            rejected.append(i)

    balances = {name: acc[0] for name, acc in accounts.items()}
    return (balances, rejected)
